async function request(url,options={}){const r=await fetch(url,options);if(!r.ok){let b=await r.json().catch(()=>({}));throw new Error(typeof b.detail==='string'?b.detail:`Request failed (${r.status})`);}return r.json();}
function useData(url){const [data,setData]=useState(null),[error,setError]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{let alive=true;const abort=new AbortController();setLoading(true);setError(null);request(url,{signal:abort.signal}).then(d=>{if(alive)setData(d)}).catch(e=>{if(alive&&e.name!=='AbortError')setError(e.message)}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false;abort.abort()}},[url]);return {data,error,loading};}
function useDebounce(value,delay=180){const [v,setV]=useState(value);useEffect(()=>{const t=setTimeout(()=>setV(value),delay);return()=>clearTimeout(t)},[value,delay]);return v;}
function Button({children,icon:Icon,onClick,primary=false,className='',...props}){return <button className={cls('btn',primary&&'primary',className)} onClick={onClick} {...props}>{Icon&&<Icon size={15}/>} {children}</button>}
